		u, err := url.Parse(n)
		if err != nil || u.Hostname() == "" {
			return nil, fmt.Errorf("X-Entire-Replicas entry %q is not a valid URL", n)
		}
		h := strings.ToLower(u.Hostname())
		sameHost := h == baseHost || strings.HasSuffix(h, "."+parent)

